mapper.select:
select
	row_number() over(order by user_id desc) as num, a.*
from (
	select *			
	from user
	where 1=1
	
	and user_id like concat('%', #{searchText}, '%')
	
	
	order by 
		
			
				user_id ${orderType}
			
			
			
				user_id desc
			
		
	
	limit #{firstIndex}, #{recordCountPerPage}
) a
